/* @autogenerated */
import { Block } from './document.model';
import { writeDocx } from './docx-writer';
import { pdfDefinition, writePdf } from './pdf-writer';

const BLOCKS: Block[] = [
  { kind: 'heading', level: 1, runs: [{ text: 'Informe' }] },
  { kind: 'paragraph', runs: [{ text: 'Hola ' }, { text: 'mundo', bold: true }, { text: '', break: true }] },
  { kind: 'list', ordered: true, start: 1, items: [[{ kind: 'paragraph', runs: [{ text: 'Uno' }] }]] },
  { kind: 'list', ordered: false, start: 1, items: [[{ kind: 'paragraph', runs: [{ text: 'A' }] }]] },
  { kind: 'table', header: [[{ text: 'Sede' }]], rows: [[[{ text: 'Madrid' }]]], align: [null] },
  { kind: 'code', text: 'a\nb' },
  { kind: 'quote', blocks: [{ kind: 'paragraph', runs: [{ text: 'cita' }] }] },
  { kind: 'rule' },
  { kind: 'pagebreak' },
];

describe('document writers', () => {
  it('writes a docx (a zip file)', async () => {
    const blob = await writeDocx(BLOCKS, 'Informe');
    const header = new Uint8Array(await blob.slice(0, 2).arrayBuffer());
    expect(blob.size).toBeGreaterThan(1000);
    expect(String.fromCharCode(...header)).toBe('PK');
  });

  it('writes a pdf', async () => {
    const blob = await writePdf(BLOCKS, 'Informe');
    const header = new Uint8Array(await blob.slice(0, 5).arrayBuffer());
    expect(String.fromCharCode(...header)).toBe('%PDF-');
  });

  it('maps every block to pdfmake content', () => {
    const content = pdfDefinition(BLOCKS).content as any[];
    expect(content.length).toBe(BLOCKS.length);
    expect(content[0]).toEqual(jasmine.objectContaining({ fontSize: 20, bold: true }));
    expect(content[2].ol.length).toBe(1);
    expect(content[3].ul.length).toBe(1);
    expect(content[4].table.body.length).toBe(2);
    expect(content[8].pageBreak).toBe('after');
  });
});
